class Diagnostic(v20b.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._test_setup = TestSetupPage(driver)
        self._test_result = TestResultPage(driver, download_checker)
        self._debug_tracing = DebugTracingPage(driver)
        self._uplink = TestModelsNRUplinkPage(driver)
        self._downlink = TestModelsNRDownlinkPage(driver)

    @property
    def test_setup(self):
        return self._test_setup

    @property
    def test_result(self):
        return self._test_result


class TestSetupPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'RF Diagnostic Test', 'Test Setup']

    def __init__(self, driver):
        super(TestSetupPage, self).__init__(driver)
        self._view_panel = TestSetupPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def configure_rf_diagnostic_test(self, activate=True, cell="All cells", bts_thresholds=None,
                                     bands_thresholds=None, timeout=10, **kwargs):
        self._view_panel.configure_rf_diagnostic_test(activate,
                                                      cell,
                                                      bts_thresholds,
                                                      bands_thresholds,
                                                      timeout,
                                                      **kwargs)

    def check_bts_thresholds_error(self, bts_thresholds, timeout=10):
        return self._view_panel.configure_and_check_bts_thresholds(bts_thresholds, timeout)

    def save_thresholds(self, timeout=30):
        return self._view_panel.save_thresholds(timeout)

    def start_rf_diagnostic_test(self, timeout=60):
        return self._view_panel.start_rf_diagnostic_test(timeout)


class TestSetupPageViewPanel(ViewPanel):
    _START_TEST_BUTTON = '//button[contains(text(), "Start Test")]'
    _TEST_STARTED = "Test started"
    _TEST_COMPLETED = "Test completed"
    _OPERATION_STARTED = "Operation started"
    _OPERATION_COMPLETED = "Operation completed"
    _TEST_STARTED_STATUS = ('//span[contains(text(), "{}") '
                            'or contains(text(), "{}")]'.format(_TEST_STARTED, _OPERATION_STARTED))
    _TEST_COMPLETED_STATUS = ('//span[contains(text(), "{}") '
                              'or contains(text(), "{}")]'.format(_TEST_COMPLETED, _OPERATION_COMPLETED))
    _SAVE_THRESHOLDS_BUTTON = '//button[contains(text(), "Save Thresholds")]'
    _SENDING_THRESHOLDS = "Sending thresholds"
    _SEND_THRESHOLDS_COMPLETED = "Sending thresholds completed"
    _SENDING_THRESHOLDS_STATUS = '//span[contains(text(), "{}")]'.format(_SENDING_THRESHOLDS)
    _SEND_THRESHOLDS_COMPLETED_STATUS = '//span[contains(text(), "{}")]'.format(_SEND_THRESHOLDS_COMPLETED)
    _ACTIVATE_REMOTE_RF_TEST_CHECK_XPATH = '//div[div[contains(text(), "Activate remote RF diagnostic test")]]//input'
    _ACTIVATE_REMOTE_RF_TEST_CLICK_XPATH = '//div[div[contains(text(), "Activate remote RF diagnostic test")]]//label'
    _START_TEST_FOR_CELL_DROPDOWN_BUTTON = '//div[div[contains(text(), "Start test for cell")]]//button'
    _START_TEST_FOR_CELL_DROPDOWN_ITEM = '//div[div[contains(text(), "Start test for cell")]]//li'
    _THRESHOLDS_FOR_BTS_LABEL = '//div[*[contains(text(), "Thresholds")]]//*[contains(text(), "{}")]'
    _THRESHOLDS_FOR_BTS_INPUT = _THRESHOLDS_FOR_BTS_LABEL + '/following-sibling::div//input'
    _BTS_THRESHOLDS_ERROR = _THRESHOLDS_FOR_BTS_LABEL + '/following-sibling::div//span[contains(@class, "triangle")]'
    _BANDS_THRESHOLD_TITLE = '//form[@name="bandsForm"]//thead//div[contains(@class, "capitalize")]'
    _DELETE_BANDS_THRESHOLDS_BUTTON = '//form[@name="bandsForm"]//tbody//button'
    _SPECIFIC_BANDS_THRESHOLD = '//form[@name="bandsForm"]//tbody//tr[{}]'
    _SPECIFIC_BANDS_THRESHOLD_INPUT = _SPECIFIC_BANDS_THRESHOLD + '//input'
    _ADD_BANDS_THRESHOLDS_BUTTON = '//form[@name="bandsForm"]//tfoot//button'
    _TDS_XPATH = '//*[@*="Test Dedicated State"]'

    def __init__(self, driver):
        super(TestSetupPageViewPanel, self).__init__(driver)

    def _configure_bands_thresholds(self, bands_thresholds, timeout):
        if not bands_thresholds:
            return

        for _ in range(len(self.driver.find_elements_by_xpath(self._DELETE_BANDS_THRESHOLDS_BUTTON))):
            elems = self.driver.find_elements_by_xpath(self._DELETE_BANDS_THRESHOLDS_BUTTON)
            elems[0].click()

        for index, bands_threshold in enumerate(bands_thresholds):
            self.click_and_wait_for_corresponding_element_visible(self._ADD_BANDS_THRESHOLDS_BUTTON,
                                                                  self._SPECIFIC_BANDS_THRESHOLD.format(index + 1))

            input_elems = self.driver.find_elements_by_xpath(self._SPECIFIC_BANDS_THRESHOLD_INPUT.format(index + 1))
            for ind, elem in enumerate(input_elems):
                elem.clear()
                elem.send_keys(bands_threshold[ind])

    def configure_and_check_bts_thresholds(self, bts_thresholds, timeout):
        if bts_thresholds:
            for threshold, value in bts_thresholds.items():
                self.insert_text_to_enable_element((By.XPATH, self._THRESHOLDS_FOR_BTS_INPUT.format(threshold.strip())),
                                                   value,
                                                   timeout)
                try:
                    self.wait_for_visibility_by_xpath(self._BTS_THRESHOLDS_ERROR.format(threshold), timeout=3)
                    logging.warning('Value for {} does not comply with the rules.'.format(threshold))
                    return False
                except TimeoutException:
                    pass
        return True

    def configure_rf_diagnostic_test(self, activate, cell, bts_thresholds, bands_thresholds, timeout, **kwargs):
        if not self.elements_is_visible((By.XPATH, self._TDS_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CHECK_XPATH,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CLICK_XPATH)
        self.select_element_from_dropdown_list_by_text_and_click(cell,
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_BUTTON),
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_ITEM),
                                                                 timeout)
        self.configure_and_check_bts_thresholds(bts_thresholds, timeout)
        self._configure_bands_thresholds(bands_thresholds, timeout)

    def save_thresholds(self, timeout):
        self.click_enabled_element((By.XPATH, self._SAVE_THRESHOLDS_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self._SENDING_THRESHOLDS_STATUS, timeout)
        logging.info(self._SENDING_THRESHOLDS)
        self.wait_for_visibility_by_xpath(self._SEND_THRESHOLDS_COMPLETED_STATUS, timeout)
        logging.info(self._SEND_THRESHOLDS_COMPLETED)
        return self._SEND_THRESHOLDS_COMPLETED

    def start_rf_diagnostic_test(self, timeout):
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self._TEST_STARTED_STATUS, timeout)
        logging.info(self._TEST_STARTED)
        self.wait_for_visibility_by_xpath(self._TEST_COMPLETED_STATUS, timeout)
        logging.info(self._TEST_COMPLETED)
        return self._TEST_COMPLETED


