class TestResultPageViewPanel(ViewPanel):
    _CELL_LIST_PANEL_XPATH = '//div[contains(@class, "cell-list-panel-body")]'
    _CELL_FILTER_INPUT_XPATH = _CELL_LIST_PANEL_XPATH + '//div[contains(@class, "cell-filter")]//input'
    _CELL_FILTERED_TR_XPATH = '//div[contains(@class, "cell-list-panel-body")]//tbody//tr'
    _GENERAL_TEST_INFORMATION_TABLE_XPATH = '//table[@data-ta-tag="general-result-table"]'
    _GENERAL_TEST_INFORMATION_TH_XPATH = _GENERAL_TEST_INFORMATION_TABLE_XPATH + '//thead//th'
    _GENERAL_TEST_INFORMATION_TR_XPATH = _GENERAL_TEST_INFORMATION_TABLE_XPATH + '//tbody//tr'
    _DETAILED_RESULT_TABLE_XPATH = '//table[@data-ta-tag="detailed-result-table"]'
    _DETAILED_RESULT_TABLE_THEAD_TR_XPATH = _DETAILED_RESULT_TABLE_XPATH + '//thead//tr'
    _DETAILED_RESULT_TABLE_TBODY_TR_XPATH = _DETAILED_RESULT_TABLE_XPATH + '//tbody//tr'
    _DETAILED_RESULT_TABLE_TBODY_TD_XPATH = _DETAILED_RESULT_TABLE_XPATH + '//tbody//tr[1]//td'
    _CLEAR_FINISHED_RESULTS_BUTTON_XPAHT = '//button[contains(text(),"Clear Finished Results")]'
    _SAVE_CELL_RESULTS_BUTTON_XPATH = '//button[contains(text(),"Save Cell Results")]'
    _SAVE_All_RESULTS_BUTTON_XPATH = '//button[contains(text(),"Save All Results")]'
    _CLEAR_FINISHED_RESULTS_SPAN_XPATH = _CLEAR_FINISHED_RESULTS_BUTTON_XPAHT + '/../following-sibling::label//span'
    _CLEAR_FINISHED_RESULTS_IN_PROGRESS_XPATH = (_CLEAR_FINISHED_RESULTS_SPAN_XPATH
                                                 + '[contains(text(), "Deleting result...")]')

    def __init__(self, driver, download_checker):
        super(TestResultPageViewPanel, self).__init__(driver, download_checker)

    def _select_cell_id(self, cell_id=None, timeout=60):
        if cell_id is None:
            return

        self.insert_text_to_enable_element((By.XPATH, self._CELL_FILTER_INPUT_XPATH), cell_id.strip(), timeout)
        filtered_elements = self.driver.find_elements_by_xpath(self._CELL_FILTERED_TR_XPATH)
        if len(filtered_elements) == 0:
            raise CellIdNotFound('cell id:{}'.format(cell_id))
        else:
            filtered_elements[0].click()

    def _get_general_test_table_content(self, timeout):
        thead_values = self.get_fields_info_from_row(self._GENERAL_TEST_INFORMATION_TH_XPATH, timeout)
        tr_elements = self.driver.find_elements_by_xpath(self._GENERAL_TEST_INFORMATION_TR_XPATH)
        tbody_values = []
        for i, tr_element in enumerate(tr_elements):
            tbody_values.append({k: '' for k in thead_values})
            for j, td_element in enumerate(tr_element.find_elements_by_xpath("td")):
                td_value = td_element.text.strip()
                tbody_values[i][thead_values[j]] = td_value
        return tbody_values

    def _get_detailed_result_table_theads(self, timeout):
        """
        table head demo:

            | port  | module   |    power   | vswr   |
            |       |          |  db  |  w  |        |
            |-------|:--------:|------------|-------:|
            | 1     | rmod     |  1   |  2  | $3,000 |

        return [["port","module","power","power","vswr"],
                ["port","module","db",   "w",    "vswr"]]
        """
        self.wait_for_visibility((By.XPATH, self._DETAILED_RESULT_TABLE_THEAD_TR_XPATH), timeout)
        thead_tr_elements = self.driver.find_elements_by_xpath(self._DETAILED_RESULT_TABLE_THEAD_TR_XPATH)
        td_elements_in_first_tr = self.driver.find_elements_by_xpath(
            self._DETAILED_RESULT_TABLE_XPATH + '//tbody//tr[1]//td')

        thead_results = ([[None for __ in range(len(td_elements_in_first_tr))] for _ in range(len(thead_tr_elements))])

        for i, tr_element in enumerate(thead_tr_elements):
            for j, th_element in enumerate(tr_element.find_elements_by_xpath("th")):
                rowspan = int(th_element.get_attribute("rowspan") or 1)
                colspan = int(th_element.get_attribute("colspan") or 1)
                th_text = th_element.text.strip()
                index_of_none_in_col = list(thead_results[i]).index(None)

                self._set_detailed_result_table_thead_values(thead_results, i, i + rowspan, index_of_none_in_col,
                                                             index_of_none_in_col + colspan, th_text)

        return thead_results

    @staticmethod
    def _set_detailed_result_table_thead_values(thead_list, row_start, row_end, column_start, column_end, value):
        for i in range(len(thead_list)):
            for j in range(len(thead_list[i])):
                if row_start <= i < row_end and column_start <= j < column_end:
                    thead_list[i][j] = value

    def _get_detailed_result_for_each_antenna_table_content(self, timeout):
        thead_values = self._get_detailed_result_table_theads(timeout)
        tr_elements = self.driver.find_elements_by_xpath(self._DETAILED_RESULT_TABLE_TBODY_TR_XPATH)
        tbody_values = []

        for i, tr_element in enumerate(tr_elements):
            tr_value = {}
            for j, td_element in enumerate(tr_element.find_elements_by_xpath("td")):
                j_column_of_thead = [i[j] for i in thead_values]
                td_value_dict = self._create_td_dict(j_column_of_thead, td_element.text.strip())
                self._append_td_dict_to_tr(tr_value, td_value_dict)
            tbody_values.append(tr_value)

        return tbody_values

    def _create_td_dict(self, thead_column, value):
        """
        demo1:
            thead: ['power','power']
            value: 1
            return {'power': '1'}
        demo2:
            thead: ['power','db']
            value: 1
            return {'power': {'db' : '1'}}

        """
        if len(set(thead_column)) == 1:
            return {thead_column[0]: value}
        else:
            return {thead_column[0]: self._create_td_dict(thead_column[1:], value)}

    def _append_td_dict_to_tr(self, tr_value, td_value):
        (key, value), = td_value.items()
        if key not in tr_value.keys():
            tr_value.update(td_value)
        else:
            self._append_td_dict_to_tr(tr_value[key], value)

    def get_general_test_information(self, cell_id=None, timeout=60):
        self._select_cell_id(cell_id, timeout)
        return self._get_general_test_table_content(timeout)

    def get_detailed_result_for_each_antenna(self, cell_id=None, timeout=60):
        self._select_cell_id(cell_id, timeout)
        return self._get_detailed_result_for_each_antenna_table_content(timeout)

    def clear_finished_results(self, timeout):
        self.click_enabled_element_after_visible(self._CLEAR_FINISHED_RESULTS_BUTTON_XPAHT, timeout)
        self.wait_for_invisibility((By.XPATH, self._CLEAR_FINISHED_RESULTS_IN_PROGRESS_XPATH), timeout)
        return self.driver.find_element_by_xpath(self._CLEAR_FINISHED_RESULTS_SPAN_XPATH).text.strip()

    def save_cell_results(self, timeout):
        start_time = time.time()
        self.click_enabled_element_after_visible(self._SAVE_CELL_RESULTS_BUTTON_XPATH, timeout)
        return self.download_files(start_time)

    def save_all_results(self, timeout):
        start_time = time.time()
        self.click_enabled_element_after_visible(self._SAVE_All_RESULTS_BUTTON_XPATH, timeout)
        return self.download_files(start_time)


class DebugTracingPage(v20b.diagnostic.DebugTracingPage):

    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)

    def configure_iq_capture(self, bbmod, ul_subcell_index_list, dl_subcell_index_list, enable_capture_on_event):
        """
        Keyword for configuring iq capture

        :param str bbmod: bbmod value
        :param ul_subcell_index_list: list of ul subcell index, list[int] or list[str]
        :type ul_subcell_index_list: list
        :param dl_subcell_index_list: dl subcell index, list[int] or list[str]
        :type dl_subcell_index_list: list
        :param bool enable_capture_on_event: if True, the capture on event option will be enabled.
        :return: None
        :rtype: NoneType
        """

        self._view_panel.configure_iq_capture(bbmod, ul_subcell_index_list, dl_subcell_index_list,
                                              enable_capture_on_event)


class DebugTracingPageViewPanel(v20b.diagnostic.DebugTracingPageViewPanel):
    _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH = '//section[@class="uPlane-component"]//div[contains(text(), "{}")]'
    _L1_IQ_CAPTURE_SUBCELL_DROPDOWN_BUTTON_XPATH = (_L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH
                                                    + '/following-sibling::div//button')
    _L1_IQ_CAPTURE_SUBCELL_DROPDOWN_OPTION_XPATH = (_L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH
                                                    + '/following-sibling::div//li')
    _L1_IQ_CAPTURE_SUBCELL_DROPDOWN_SELECTED_OPTION_XPATH = (_L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH
                                                             + '/following-sibling::div//li')
    _UL_SUBCELL = "UL subcell list"
    _DL_SUBCELL = "DL subcell list"

    def __init__(self, driver):
        super(DebugTracingPageViewPanel, self).__init__(driver)

    def _clear_selected_subcells(self, subcell_label):
        selected_elements = self.expand_dropdown_list_and_return_elements(
            button_locator=(By.XPATH, self._L1_IQ_CAPTURE_SUBCELL_DROPDOWN_BUTTON_XPATH.format(subcell_label)),
            option_locator=(By.XPATH, self._L1_IQ_CAPTURE_SUBCELL_DROPDOWN_SELECTED_OPTION_XPATH.format(subcell_label) + '//input'))

        for ele in selected_elements[::-1]:
            if ele.is_selected():
                ele.click()

        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_SUBCELL_DROPDOWN_BUTTON_XPATH.format(subcell_label)))

    def _select_subcell_list(self, subcell_label, subcell_index_list):
        if not subcell_index_list:
            return
        self._clear_selected_subcells(subcell_label)

        elements = self.expand_dropdown_list_and_return_elements(
            button_locator=(By.XPATH, self._L1_IQ_CAPTURE_SUBCELL_DROPDOWN_BUTTON_XPATH.format(subcell_label)),
            option_locator=(By.XPATH, self._L1_IQ_CAPTURE_SUBCELL_DROPDOWN_OPTION_XPATH.format(subcell_label)))

        for subcell_index in subcell_index_list:
            self.find_element_from_group_by_text(elements, subcell_index).click()

        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_SUBCELL_DROPDOWN_BUTTON_XPATH.format(subcell_label)))

    def configure_iq_capture(self, bbmod, ul_subcell_index_list, dl_subcell_index_list, enable_capture_on_event):
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_bbmod(bbmod)
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)
        self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)
        self._select_subcell_list(self._DL_SUBCELL, dl_subcell_index_list)
        self.select_checkbox_by_specified_status(enable_capture_on_event,
                                                 self._CAPTURE_EVENT_INPUT_XPATH,
                                                 self._CAPTURE_EVENT_CHECKOUT_XPATH)
        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))


